#include <string>
#include <map>
#include <stack>
#include <cctype>

using namespace std;

class Solution {
public:
    string countOfAtoms(string formula) {
        stack<map<string, int>> stk;
        map<string, int> cur;
        int i = 0, n = formula.length();

        while (i < n) {
            if (formula[i] == '(') {
                stk.push(cur);
                cur.clear();
                ++i;
            } else if (formula[i] == ')') {
                ++i;
                int start = i, count = 0;
                while (i < n && isdigit(formula[i])) ++i;
                count = start < i ? stoi(formula.substr(start, i - start)) : 1;

                for (auto& p : cur)
                    p.second *= count;

                auto top = stk.top(); stk.pop();
                for (auto& p : cur)
                    top[p.first] += p.second;

                cur = top;
            } else {
                int start = i++;
                while (i < n && islower(formula[i])) ++i;
                string name = formula.substr(start, i - start);
                start = i;
                while (i < n && isdigit(formula[i])) ++i;
                int count = start < i ? stoi(formula.substr(start, i - start)) : 1;
                cur[name] += count;
            }
        }

        string res;
        for (auto& [atom, count] : cur) {
            res += atom;
            if (count > 1) res += to_string(count);
        }
        return res;
    }
};
